func EnvOrAndChanged(name, def string) (v string, changed bool) {
	val := Getenv(name)
	if val != "" {
		v = val
		if g, ok := envCache.goroot[name]; ok {
			changed = val != g
		} else {
			changed = val != def
		}
		return v, changed
	}
	return def, false
}

